function findWords(board: string[][], words: string[]): string[] {
  type Node = { next: Map<string, Node>; word: string | null }
  const root: Node = { next: new Map(), word: null }
  for (const w of words) {
    let node = root
    for (const ch of w) {
      if (!node.next.has(ch)) node.next.set(ch, { next: new Map(), word: null })
      node = node.next.get(ch)!
    }
    node.word = w
  }
  const m = board.length
  const n = board[0].length
  const found: string[] = []
  function dfs(r: number, c: number, parent: Node) {
    const ch = board[r][c]
    const node = parent.next.get(ch)
    if (!node) return
    if (node.word !== null) {
      found.push(node.word)
      node.word = null
    }
    board[r][c] = '#'
    for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const nr = r + dr
      const nc = c + dc
      if (nr >= 0 && nc >= 0 && nr < m && nc < n && board[nr][nc] !== '#') dfs(nr, nc, node)
    }
    board[r][c] = ch
  }
  for (let r = 0; r < m; r++) for (let c = 0; c < n; c++) dfs(r, c, root)
  return found
}
